import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    target_state = inputs["target_state"]
    cdc_events = inputs["cdc_events"]

    # 1. Apply each distinct seq only once (at-least-once delivery dedup).
    events = cdc_events.drop_duplicates(subset=["seq"], keep="first").copy()

    # Build mutable per-order state from target_state.
    state = {}
    for row in target_state.itertuples(index=False):
        state[row.order_id] = {
            "status": row.status,
            "amount": row.amount,
            "last_seq": row.last_seq,
        }

    orig_last_seq = {oid: s["last_seq"] for oid, s in state.items()}
    orig_exists = set(state.keys())

    # 2. Replay guard against the ORIGINAL target_state (not the evolving state).
    if len(events) > 0:
        events["_orig_last_seq"] = events["order_id"].map(orig_last_seq)
        events["_has_orig"] = events["order_id"].isin(orig_exists)
        keep_mask = (~events["_has_orig"]) | (events["seq"] > events["_orig_last_seq"])
        events = events[keep_mask].drop(columns=["_orig_last_seq", "_has_orig"])

    # 3. Apply remaining events in seq order.
    events = events.sort_values("seq", kind="mergesort")

    # Track last applied event (op, seq) per order, for orders that actually
    # had something happen to their row (a D on a missing row is a no-op and
    # does not count).
    last_applied = {}

    for row in events.itertuples(index=False):
        oid = row.order_id
        op = row.op
        seq = row.seq

        if op in ("I", "U"):
            if oid in state:
                existing = state[oid]
                if op == "U":
                    if pd.notna(row.amount):
                        new_amount = row.amount
                    else:
                        new_amount = existing["amount"]
                else:  # 'I' on an existing row: amount always set to event amount
                    new_amount = row.amount
                state[oid] = {
                    "status": row.status,
                    "amount": new_amount,
                    "last_seq": seq,
                }
            else:
                # Creation: amount taken as-is (NULL stays NULL), regardless of I/U.
                state[oid] = {
                    "status": row.status,
                    "amount": row.amount,
                    "last_seq": seq,
                }
            last_applied[oid] = ("X", seq)
        elif op == "D":
            if oid in state:
                del state[oid]
                last_applied[oid] = ("D", seq)
            # D on a missing order does nothing, and does not affect last_applied.

    # 4. new_state = target_state after all events (unchanged orders carried forward).
    if state:
        new_state = pd.DataFrame(
            [
                {
                    "order_id": oid,
                    "status": info["status"],
                    "amount": info["amount"],
                    "last_seq": info["last_seq"],
                }
                for oid, info in state.items()
            ]
        )
    else:
        new_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])

    new_state["order_id"] = new_state["order_id"].astype("int64")
    new_state["status"] = new_state["status"].astype(object)
    new_state["amount"] = new_state["amount"].astype("float64")
    new_state["last_seq"] = new_state["last_seq"].astype("int64")

    # 5. tombstones: orders whose last applied event was a 'D'.
    tomb_rows = [
        {"order_id": oid, "deleted_seq": seq}
        for oid, (op, seq) in last_applied.items()
        if op == "D"
    ]
    if tomb_rows:
        tombstones = pd.DataFrame(tomb_rows)
    else:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])

    tombstones["order_id"] = tombstones["order_id"].astype("int64")
    tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")

    return {"new_state": new_state, "tombstones": tombstones}
